SELECT setval('rootcause.root_causes_purges_row_id_seq', GREATEST((SELECT COALESCE(max(row_id),0) FROM rootcause.root_causes_purges),1), (SELECT count(*) FROM rootcause.root_causes_purges) > 0);

DO $do$
BEGIN
